import{_ as t}from"./chunks/main_page.iLigAlA3.js";import{_ as o}from"./chunks/main_page_drag.c4Bat0TW.js";import{_ as a,o as r,c as i,a0 as n}from"./chunks/framework.akKRIpjQ.js";const b=JSON.parse('{"title":"01 · Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01-getting-started.md","filePath":"guide/01-getting-started.md"}'),s={name:"guide/01-getting-started.md"};function l(d,e,c,h,g,u){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_01-·-getting-started" tabindex="-1">01 · Getting Started <a class="header-anchor" href="#_01-·-getting-started" aria-label="Permalink to &quot;01 · Getting Started&quot;">​</a></h1><blockquote><p>From zero to &quot;first restring reminder&quot; — about <strong>5 minutes</strong>.</p></blockquote><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="install-apk-android" tabindex="-1">Install APK (Android) <a class="header-anchor" href="#install-apk-android" aria-label="Permalink to &quot;Install APK (Android)&quot;">​</a></h3><ol><li>Pick a source from the <a href="./../#download">Download</a> page, download <code>app-release.apk</code></li><li>The first time you open it, Android blocks &quot;unknown sources&quot;: <ul><li><code>Settings → Apps → Special app access → Install unknown apps</code></li><li>Select your browser / file manager and turn on &quot;Allow from this source&quot;</li></ul></li><li>Tap the APK again → <code>Install anyway</code> → <code>Done</code></li></ol><blockquote><p>iOS users: there is no available build — see <a href="./00-introduction.html#supported-platforms">00 · Platforms</a>.</p></blockquote><h2 id="launch" tabindex="-1">Launch <a class="header-anchor" href="#launch" aria-label="Permalink to &quot;Launch&quot;">​</a></h2><p>Tap the desktop icon. On first launch the App does <strong>three things</strong>:</p><ol><li>Initializes the local SQLite database (rackets, stringing log)</li><li>Requests &quot;Notifications&quot; permission (for restring reminders)</li><li>Shows the home screen directly — <strong>no account, no login</strong></li></ol><blockquote><p>Notifications declined? Don&#39;t worry — you can re-enable under <code>Settings → Notifications</code>, but <strong>without notifications you will not get restring reminders</strong>.</p></blockquote><h2 id="home-—-the-four-features" tabindex="-1">Home — the four features <a class="header-anchor" href="#home-—-the-four-features" aria-label="Permalink to &quot;Home — the four features&quot;">​</a></h2><img src="'+t+'" alt="AceCrush Craft home screen" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>The home screen is two big cards on top + the feature grid:</p><table tabindex="0"><thead><tr><th>Card</th><th>What it does</th></tr></thead><tbody><tr><td><strong>AI grip size</strong></td><td>Snap a palm photo → recommended grip size</td></tr><tr><td><strong>Tension conversion</strong></td><td>DT ⇄ RT ⇄ lbs ⇄ kg cross-calculator</td></tr></tbody></table><p>The feature grid below has:</p><ul><li><strong>AI grip size</strong> — same as the top card</li><li><strong>Racket profile</strong> — your collection of rackets</li><li><strong>Stringing log</strong> — restring history + reminders</li><li><strong>Tension conversion</strong> — same as the top card</li><li><strong>Settings</strong> — theme, units, privacy, feedback, open-source licenses</li></ul><blockquote><p><strong>Drag the home grid</strong> to reorder features; long-press to drop one onto the home cards. The order is <strong>per-device only</strong>.</p></blockquote><img src="'+o+'" alt="Drag-and-drop reorder on home" style="max-width:320px;border-radius:12px;margin:12px 0;"><h2 id="turn-on-notifications-the-most-important-step" tabindex="-1">Turn on notifications (the most important step) <a class="header-anchor" href="#turn-on-notifications-the-most-important-step" aria-label="Permalink to &quot;Turn on notifications (the most important step)&quot;">​</a></h2><p>If notifications stay off → restring reminders never fire. <strong>Strongly recommended as the very first thing to do</strong>:</p><ol><li>Open <code>Me</code> tab → <code>Notifications &amp; reminders</code></li><li>Toggle &quot;Restring reminders&quot; on → in Android system settings, allow this App to send notifications</li><li>Set a reminder time window (default <code>09:00</code>; change to <code>20:00</code> / <code>12:00</code> if you prefer evening)</li></ol><blockquote><p>If you later don&#39;t want notifications, just turn them off again.</p></blockquote><h2 id="three-bottom-tabs" tabindex="-1">Three bottom tabs <a class="header-anchor" href="#three-bottom-tabs" aria-label="Permalink to &quot;Three bottom tabs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>What you do here</th></tr></thead><tbody><tr><td><strong>Home</strong></td><td>All four features, big cards on top + grid</td></tr><tr><td><strong>Rackets</strong></td><td>Profile list, stringing log, reminder settings</td></tr><tr><td><strong>Me</strong></td><td>Theme / language / units / privacy / feedback / open-source licenses</td></tr></tbody></table><h2 id="walk-through-add-your-first-racket-and-record-a-restring" tabindex="-1">Walk-through: add your first racket and record a restring <a class="header-anchor" href="#walk-through-add-your-first-racket-and-record-a-restring" aria-label="Permalink to &quot;Walk-through: add your first racket and record a restring&quot;">​</a></h2><p>This is the minimum path to feel the App&#39;s value:</p><h3 id="step-1-—-add-a-racket-03-·-rackets" tabindex="-1">Step 1 — Add a racket (<a href="./03-racquets.html">03 · Rackets</a>) <a class="header-anchor" href="#step-1-—-add-a-racket-03-·-rackets" aria-label="Permalink to &quot;Step 1 — Add a racket ([03 · Rackets](./03-racquets))&quot;">​</a></h3><ol><li><code>Rackets</code> tab → <code>+ Add racket</code></li><li>Enter at least 4 fields: <strong>Name</strong>, <strong>Brand</strong>, <strong>Model</strong>, <strong>Headsize</strong></li><li>Optional: length / weight / balance / notes</li><li><code>Save</code></li></ol><h3 id="step-2-—-record-a-restring-04-·-stringing-log" tabindex="-1">Step 2 — Record a restring (<a href="./04-stringing-log.html">04 · Stringing log</a>) <a class="header-anchor" href="#step-2-—-record-a-restring-04-·-stringing-log" aria-label="Permalink to &quot;Step 2 — Record a restring ([04 · Stringing log](./04-stringing-log))&quot;">​</a></h3><ol><li>In the racket detail page, <code>Stringing log</code> tab → <code>+ Add stringing record</code></li><li>Fill: date (default today), string model, tension (main / cross), optional stringer name, notes</li><li><code>Save</code></li></ol><h3 id="step-3-—-set-a-restring-reminder" tabindex="-1">Step 3 — Set a restring reminder <a class="header-anchor" href="#step-3-—-set-a-restring-reminder" aria-label="Permalink to &quot;Step 3 — Set a restring reminder&quot;">​</a></h3><p>Still in the racket detail → <code>Set restring reminder</code> → pick a rule:</p><ul><li><strong>By time</strong> (default 90 days later)</li><li><strong>By play hours</strong> (your weekly sessions × duration → estimate)</li></ul><p>Pick the reminder time window.</p><blockquote><p>You don&#39;t need to log any data? The reminder still fires — it just reads &quot;Time to check your strings&quot;.</p></blockquote><h2 id="theme-language-units" tabindex="-1">Theme, language, units <a class="header-anchor" href="#theme-language-units" aria-label="Permalink to &quot;Theme, language, units&quot;">​</a></h2><p><code>Me</code> tab:</p><ul><li><strong>Theme</strong>: Follow system / Light / Dark (V1.1+ adds OLED pure black)</li><li><strong>Units</strong>: length = mm / inches; weight = g / oz; tension = lbs / kg</li><li><strong>Language</strong>: 简体中文 (V1.0) + English (V1.0+)</li></ul><blockquote><p><strong>Language setting only affects the App display</strong> — it won&#39;t translate your notes or racket names.</p></blockquote><h2 id="first-feedback" tabindex="-1">First feedback <a class="header-anchor" href="#first-feedback" aria-label="Permalink to &quot;First feedback&quot;">​</a></h2><p><code>Me</code> tab → <code>Feedback &amp; suggestions</code>:</p><ul><li>One-sentence description → <code>Send</code></li><li>The feedback record carries the App version + device basics (OS version / screen resolution, <strong>no</strong> account info or your private data)</li></ul><p>See <a href="./06-settings-faq.html#feedback">06 · Feedback</a>.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><h3 id="after-uninstall-is-the-data-still-there" tabindex="-1">After uninstall, is the data still there? <a class="header-anchor" href="#after-uninstall-is-the-data-still-there" aria-label="Permalink to &quot;After uninstall, is the data still there?&quot;">​</a></h3><p><strong>No</strong>. All data is stored in the App sandbox (Android: <code>/data/data/com.acecrushcraft.app/databases/</code>); uninstalling wipes it. Before installing V1.1, do <code>Settings → Export</code> for a JSON backup.</p><h3 id="when-is-ios-coming" tabindex="-1">When is iOS coming? <a class="header-anchor" href="#when-is-ios-coming" aria-label="Permalink to &quot;When is iOS coming?&quot;">​</a></h3><p>No ETA yet. We are polishing Android V1.0 / V1.1 first; iOS is planned.</p><h3 id="does-it-work-with-the-network-off" tabindex="-1">Does it work with the network off? <a class="header-anchor" href="#does-it-work-with-the-network-off" aria-label="Permalink to &quot;Does it work with the network off?&quot;">​</a></h3><p>Yes, except for:</p><ul><li>Feedback submission</li></ul><p>See <a href="./00-introduction.html#1-offline-first">00 · Three pillars · Offline-first</a> and <a href="./06-settings-faq.html#privacy--permissions">06 · Privacy &amp; permissions</a>.</p>',52)])])}const k=a(s,[["render",l]]);export{b as __pageData,k as default};
